const viewer = (window.viewer = new Cesium.Viewer('cesiumContainer', {
  baseLayer: new Cesium.ImageryLayer(new Cesium.OpenStreetMapImageryProvider({
    url: 'https://tile.openstreetmap.org/',
    maximumLevel: 18
  })),
  baseLayerPicker: false,
  navigationHelpButton: false,
  animation: false,
  timeline: false,
  geocoder: false,
  homeButton: false,
  sceneModePicker: false,
  fullscreenButton: false,
  infoBox: false,
  selectionIndicator: false
}));

viewer.scene.globe.enableLighting = false;

// Mark the Empire State Building with a visible point and label
viewer.entities.add({
  name: 'Empire State Building',
  position: Cesium.Cartesian3.fromDegrees(-73.9857, 40.7484, 443.0),
  point: {
    pixelSize: 14,
    color: Cesium.Color.YELLOW,
    outlineColor: Cesium.Color.BLACK,
    outlineWidth: 2
  },
  label: {
    text: 'Empire State Building',
    font: '13pt sans-serif',
    fillColor: Cesium.Color.WHITE,
    outlineColor: Cesium.Color.BLACK,
    outlineWidth: 2,
    style: Cesium.LabelStyle.FILL_AND_OUTLINE,
    verticalOrigin: Cesium.VerticalOrigin.BOTTOM,
    pixelOffset: new Cesium.Cartesian2(0, -16)
  }
});

// Target at ground level of the Empire State Building
const target = Cesium.Cartesian3.fromDegrees(-73.9857, 40.7484, 0.0);

// Heading 180° = camera is north of target, facing south down Manhattan
// Pitch -30° = 30-degree downward angle to reveal the building and the grid behind it
viewer.camera.lookAt(
  target,
  new Cesium.HeadingPitchRange(
    Cesium.Math.toRadians(180.0),
    Cesium.Math.toRadians(-30.0),
    1500.0
  )
);
```

The camera is placed 1,500 m north of the Empire State Building with a 30° downward pitch (`-30`). Heading `180°` means the camera faces south — per the skill's cardinal reference table, "view from north → camera faces south → heading 180°". This frames the ESB in the foreground with Midtown and Lower Manhattan's street grid receding southward behind it.

